// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // First set owner to this contract so owned() can succeed
        vm.prank(c.owner());
        c.transferOwnership(address(this));
        // Call owned() - in reference C it always succeeds; in mutant it may succeed
        c.owned();
        // Now try to transfer ownership to newOwner
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

